/* engines/waviz.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  /* Waviz supplies a live Web Audio visualisation drawn on a canvas in the
     waveform row; playback itself uses the same shared <audio> element. */
  async function createWaviz(url, startAt, autoplay) {
    try { await P.loadWavizScript(); } catch {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }
    const WavizClass = P.wavizConstructor();
    if (!WavizClass) return false;

    const context = P.sharedAudioContext();
    if (!context) {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }

    const canvas = document.createElement("canvas");
    canvas.className = "player-waviz-canvas";
    canvas.width = 1024;
    canvas.height = 56;
    canvas.setAttribute("aria-hidden", "true");
    P.waveform.appendChild(canvas);
    P.wavizCanvas = canvas;
    P.showWaveMode();
    P.audio.src = url;
    P.audio.load();

    try {
      P.waviz = new WavizClass(canvas, P.audio, context);
    } catch {
      P.wavizCanvas?.remove();
      P.wavizCanvas = null;
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }

    P.wavizPlayHandler = () => {
      if (!P.waviz) return;
      try { P.waviz.simpleLine(P.cssVar("--text") || "#ffffff").catch(() => {}); } catch {}
    };
    P.wavizPauseHandler = () => {
      try { P.waviz?.stop(); } catch {}
    };
    P.audio.addEventListener("play", P.wavizPlayHandler);
    P.audio.addEventListener("pause", P.wavizPauseHandler);

    if (startAt) P.setTime(startAt);
    if (autoplay) P.attemptPlay();
    return true;
  }
  Object.assign(P, { createWaviz });
}
